  data.addresses=(data.addresses||[]).map(item=>({...item,original:item.address,deleted:false,is_new:false}));
  data.originalEnvlists=[...(data.envlists||[])]; data.listenPort=String(data.settings.find(item=>item.kind==="port")?.value||""); data.originalListenPort=data.listenPort; data.portEditing=false; data.addressEditing=false; data.regenerateServerKey=false; data.regenerateHeaderProtectionKey=false; data.addingVariable=false;
